SELECT patient_id, name, region_id, shard_key, email, phone, date_of_birth, address, created_at, updated_at
FROM patients
WHERE patient_id = #{patientId}

SELECT patient_id, name, region_id, shard_key, email, phone, date_of_birth, address, created_at, updated_at
FROM patients
WHERE patient_id = #{patientId} AND shard_key = #{shardKey}

SELECT patient_id, name, region_id, shard_key, email, phone, date_of_birth, address, created_at, updated_at
FROM patients
WHERE region_id = #{regionId} AND shard_key = #{shardKey}
